216	
217		for d := range dbDirs {
218			if _, ok := fsDirs[d]; !ok {
219				deleted = append(deleted, d)
220			}
221		}
222	
223		sort.Strings(deleted)
224		log.Debug(ctx, "Finished deleted folders check", "total", len(deleted), "elapsed", time.Since(start))
225		return deleted
226	}
