228	func (s *TagScanner) processDeletedDir(ctx context.Context, dir string, fsDirs dirMap) error {
229		start := time.Now()
230		buffer := newRefresher(ctx, s.ds, fsDirs)
231	
232		mfs, err := s.ds.MediaFile(ctx).FindAllByPath(dir)
233		if err != nil {
234			return err
235		}
236	
237		c, err := s.ds.MediaFile(ctx).DeleteByPath(dir)
238		if err != nil {
239			return err
240		}
241		s.cnt.deleted += c
242	
243		for _, t := range mfs {
244			buffer.accumulate(t)
245			s.cacheWarmer.AddAlbum(ctx, t.AlbumID)
246		}
247	
248		err = buffer.flush()
249		log.Info(ctx, "Finished processing deleted folder", "dir", dir, "purged", len(mfs), "elapsed", time.Since(start))
250		return err
251	}
