 72	func (f *refresher) refreshAlbums(ids ...string) error {
 73		mfs, err := f.ds.MediaFile(f.ctx).GetAll(model.QueryOptions{Filters: squirrel.Eq{"album_id": ids}})
 74		if err != nil {
 75			return err
 76		}
 77		if len(mfs) == 0 {
 78			return nil
 79		}
 80	
 81		repo := f.ds.Album(f.ctx)
 82		grouped := slice.Group(mfs, func(m model.MediaFile) string { return m.AlbumID })
 83		for _, songs := range grouped {
 84			albumFiles := model.MediaFiles(songs)
 85			a := albumFiles.ToAlbum()
 86			a.ImageFiles = imageFilesForAlbum(albumFiles, f.dirs)
 87			err := repo.Put(&a)
 88			if err != nil {
 89				return err
 90			}
 91		}
 92		return nil
 93	}
 94	
 95	// imageFilesForAlbum joins images found alongside an album's media files into a path list.
 96	func imageFilesForAlbum(mfs model.MediaFiles, dirs dirMap) string {
 97		var paths []string
 98		for _, dir := range mfs.Dirs() {
 99			for _, name := range dirs[dir].ImageFiles {
100				paths = append(paths, filepath.Join(dir, name))
101			}
102		}
103		return strings.Join(paths, string(filepath.ListSeparator))
104	}
