106	func (f *refresher) flush() error {
107		err := f.flushMap(f.album, "album", f.chunkRefreshAlbums)
108		if err != nil {
109			return err
110		}
111		err = f.flushMap(f.artist, "artist", f.ds.Artist(f.ctx).Refresh) // TODO Move Artist Refresh out of persistence
112		if err != nil {
113			return err
114		}
115		return nil
116	}
